    knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]

    # BFS to precompute shortest paths between all points of interest on a 50x50 board
    for i in range(num_points):
        start_x, start_y = points[i]
        dists = [[float('inf')] * 50 for _ in range(50)]
        dists[start_x][start_y] = 0
        queue = deque([(start_x, start_y)])
        while queue:
            cx, cy = queue.popleft()
            for dx, dy in knight_moves:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and dists[nx][ny] == float('inf'):
                    dists[nx][ny] = dists[cx][cy] + 1
                    queue.append((nx, ny))
        for j in range(num_points):
            dist_matrix[i][j] = dists[points[j][0]][points[j][1]]

    memo = {}

    def solve(curr_idx: int, mask: int, is_alice: bool) -> float:
        # If no pawns left, sum of moves is 0
        if mask == 0:
            return 0

        state = (curr_idx, mask, is_alice)
        if state in memo:
            return memo[state]

        res = -float('inf') if is_alice else float('inf')

        # Try capturing every available pawn
        for i in range(1, num_points):
            if (mask >> (i - 1)) & 1:
                d = dist_matrix[curr_idx][i]
                # The result of the game from this point onwards
                sub_res = solve(i, mask ^ (1 << (i - 1)), not is_alice)

                current_total = d + sub_res
                if is_alice:
                    if current_total > res:
                        res = current_total
                else:
                    if current_total < res:
                        res = current_total

        memo[state] = float(res)
        return res

    # Initial state: knight at index 0, all pawns (1 to num_points-1) are present
    initial_mask = (1 << (num_points - 1)) - 1
    result = solve(0, initial_mask, True)
    return int(result)
